import{_ as s,o as e,c as n,a5 as t}from"./chunks/framework.DAcoJo3K.js";const u=JSON.parse('{"title":"全局共享状态容器","description":"","frontmatter":{"title":"全局共享状态容器"},"headers":[],"relativePath":"guide/01-global-shared-store.md","filePath":"guide/01-global-shared-store.md"}'),o={name:"guide/01-global-shared-store.md"};function p(r,a,l,i,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="全局共享状态容器" tabindex="-1">全局共享状态容器 <a class="header-anchor" href="#全局共享状态容器" aria-label="Permalink to &quot;全局共享状态容器&quot;">​</a></h1><blockquote><p>本章属于 primitive 层。前置：无（全书地基章之一）。 学完你能：用一个模块级可变单例对象充当扩展全生命周期的共享内存，让命令、侧边栏、详情面板三条战线零胶水互相通信——同时清楚这套&quot;全局可变&quot;换来的是什么、付的代价是什么。</p></blockquote><h2 id="_1-为什么需要它-全书的地基" tabindex="-1">1. 为什么需要它（全书的地基） <a class="header-anchor" href="#_1-为什么需要它-全书的地基" aria-label="Permalink to &quot;1. 为什么需要它（全书的地基）&quot;">​</a></h2><p>本书讲的是一个 VSCode 扩展，它要在编辑器里塞下知乎的大部分功能：热榜侧边栏、推荐流、关注、搜索、详情面板、收藏夹、评论、扫码登录，还要在老板走过来时一键伪装成代码编辑器。这些功能跑起来后会同时存在好几条独立战线：</p><ul><li><strong>命令处理</strong>：几十个 registered command，分散在不同文件，被 VSCode 在用户点按钮时回调。</li><li><strong>侧边栏 provider</strong>：四个 TreeDataProvider，各自管一份列表，按需刷新。</li><li><strong>详情面板</strong>：用户点开几篇文章，每篇一个 webview panel，互不阻塞。</li><li><strong>反爬浏览器</strong>：一台真实 Chrome 进程，按需为某篇文章开页面、跑 JS 提数据。</li><li><strong>状态栏项</strong>：状态栏上若干按钮，被 webview 切换时刷新。</li></ul><p>这些战线彼此要找对方。点开详情要知道点的是哪条；投票命令要知道改的是哪个面板；反爬浏览器要知道现在为哪个面板服务；登录流程要把凭证交给侧边栏刷新用。</p><p>最朴素的解法是构造函数逐层传：构造 service 时把 panel map、browser、cookie、provider 全传进去；构造命令组时把 service 再传进去。这条路走得下去，但扩展每加一个子系统，就要改一串构造签名——命令注册表慢慢就长成了一个手写的依赖注入容器，胶水代码淹没业务逻辑。</p><p>本书后续几乎所有章节都站在这个矛盾的某一侧。本章作为第一章，先把这块<strong>地基</strong>摆出来：<strong>用一个模块级导出的可变对象，当扩展全生命周期的共享内存</strong>。后续章节（浏览器、侧边栏、详情、伪装、命令编排）都只往这个容器里塞自己的实例/数据，<strong>不</strong>再讲&quot;为什么用全局容器&quot;这件事。</p><h2 id="_2-核心思想" tabindex="-1">2. 核心思想 <a class="header-anchor" href="#_2-核心思想" aria-label="Permalink to &quot;2. 核心思想&quot;">​</a></h2><p><strong>把扩展全生命周期的资源和数据都挂在一个模块级 <code>export const</code> 可变单例对象上，谁需要谁 import</strong>。</p><p>任何文件 <code>import { Store } from &quot;./stores&quot;</code> 拿到的都是同一个引用——单例性在 ES 模块层就保证了，无需任何 IoC 容器。</p><h2 id="_3-心智模型" tabindex="-1">3. 心智模型 <a class="header-anchor" href="#_3-心智模型" aria-label="Permalink to &quot;3. 心智模型&quot;">​</a></h2><p>容器是一个对象字面量，导出时所有字段都是空的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Store = {</span></span>
<span class="line"><span>  context: null          // 扩展上下文槽位</span></span>
<span class="line"><span>  webviewMap: Map        // id → 详情面板实例</span></span>
<span class="line"><span>  browserInstance: null  // 反爬浏览器实例槽位</span></span>
<span class="line"><span>  pagesInstance: Map     // id → 浏览器页面实例（与面板共享同一 id）</span></span>
<span class="line"><span>  statusBarMap: Map</span></span>
<span class="line"><span>  Zhihu: {</span></span>
<span class="line"><span>    hot:   { list: [], isLoading: false }   // recommend/follow/search 同构</span></span>
<span class="line"><span>    cookie: &quot;&quot;                              // 凭证：一处写入，全局可读</span></span>
<span class="line"><span>    // ...</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,14)])])}const g=s(o,[["render",p]]);export{u as __pageData,g as default};
